# Putting layers together: a refund tool that stays safe even if the model is tricked.

def issue_refund(order_id, amount, *, current_user_id):
    # Layer 1: least privilege — only this user's own orders are reachable.
    order = db.get_order(order_id, owner=current_user_id)
    if order is None:
        raise PermissionError("Not your order")

    # Input validation in code, not just trusted from the model's output.
    if not (0 < amount <= order.total):
        raise ValueError("Refund exceeds order total")

    # Layer 4: human approval required for larger amounts.
    if amount > AUTO_APPROVE_LIMIT:
        return request_human_approval(order_id, amount)  # agent cannot finish alone

    # Layer 5: rate limiting, so no runaway loop of refunds is possible.
    if refunds_today(current_user_id) >= DAILY_REFUND_CAP:
        raise RuntimeError("Refund limit reached")

    log_action("refund", order_id, amount, current_user_id)   # Layer 6: logging
    return payment_api.refund(order_id, amount)
